<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { Edit, Refresh, Search, Tickets } from '@element-plus/icons-vue'
import { api, hasPermission } from '../api'
import '../lead-operations.css'

const loading = ref(false); const saving = ref(false); const error = ref(''); const data = ref({ records: [], total: 0, current: 1, size: 20 }); const canOperate = computed(() => hasPermission('platform:write'))
const filter = reactive({ status: '', keyword: '' }); const page = ref(1); const dialogVisible = ref(false); const eventLoading = ref(false); const events = ref([]); const selected = ref(null); const form = reactive({ status: '', remark: '', nextActionAt: '' })
const labels = { MATCHED: '候选对接', CONTACTED: '已进入对接', INTENT: '有意向', WON: '已成交', LOST: '已关闭' }; const types = { MATCHED: 'primary', CONTACTED: 'primary', INTENT: 'warning', WON: 'success', LOST: 'info' }
const confirmation = value => value === 'ACCEPTED' ? '已确认' : value === 'DECLINED' ? '暂不对接' : '待确认'; const formatDate = value => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '未设置'
const transitions = computed(() => transitionsFor(selected.value?.status).map(value => ({ value, label: labels[value] })))
const query = () => new URLSearchParams(Object.entries({ ...filter, page: page.value, size: 20 }).filter(([, value]) => value !== '' && value != null)).toString()
async function responseMessage(response, fallback) { try { return (await response.json()).message || fallback } catch { return fallback } }
async function load() { if (!canOperate.value) return; loading.value = true; error.value = ''; try { const response = await api(`/api/operations/leads?${query()}`); if (!response.ok) throw new Error(await responseMessage(response, '线索列表加载失败')); data.value = await response.json() } catch (e) { error.value = e.message } finally { loading.value = false } }
async function loadEvents(id) { eventLoading.value = true; events.value = []; try { const response = await api(`/api/operations/leads/${id}/events`); if (!response.ok) throw new Error(await responseMessage(response, '过程记录加载失败')); events.value = await response.json() } catch (e) { error.value = e.message } finally { eventLoading.value = false } }
async function openFollow(row) { selected.value = row; Object.assign(form, { status: transitionsFor(row.status)[0] || '', remark: row.remark || '', nextActionAt: row.nextActionAt || '' }); dialogVisible.value = true; await loadEvents(row.id) }
function transitionsFor(status) { return status === 'MATCHED' ? ['CONTACTED', 'LOST'] : status === 'CONTACTED' ? ['INTENT', 'LOST'] : status === 'INTENT' ? ['WON', 'LOST'] : [] }
async function saveFollow() { if (!form.status) { error.value = '当前线索已结束，不能继续跟进。'; return } saving.value = true; error.value = ''; try { const response = await api(`/api/operations/leads/${selected.value.id}/follow`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); if (!response.ok) throw new Error(await responseMessage(response, '线索跟进保存失败')); dialogVisible.value = false; await load() } catch (e) { error.value = e.message } finally { saving.value = false } }
function search() { page.value = 1; load() }
onMounted(load)
</script>

<template>
  <section class="lead-operations" v-loading="loading"><header class="lead-header"><div><h1>线索运营</h1><p>维护客户需求、供应商确认和后续对接结果；每个动作都会保留完整记录。</p></div><div class="lead-header-actions"><RouterLink class="el-button" to="/admin">审核后台</RouterLink><el-button :icon="Refresh" @click="load">刷新</el-button></div></header><el-alert v-if="error" class="lead-alert" :title="error" type="error" show-icon closable @close="error=''" />
    <template v-if="canOperate"><form class="lead-filter" @submit.prevent="search"><el-select v-model="filter.status" aria-label="线索状态"><el-option label="全部状态" value="" /><el-option v-for="(label, value) in labels" :key="value" :label="label" :value="value" /></el-select><el-input v-model="filter.keyword" :prefix-icon="Search" placeholder="需求、客户组织或供应商名称" clearable /><el-button type="primary" native-type="submit">查询</el-button></form><section class="lead-table-wrap"><div class="lead-caption"><span>对接线索</span><small>共 {{ data.total }} 条</small></div><el-table :data="data.records" empty-text="当前筛选条件下没有线索"><el-table-column prop="demandTitle" label="客户需求" min-width="205" /><el-table-column prop="customerOrganization" label="客户组织" min-width="170" show-overflow-tooltip /><el-table-column prop="supplierName" label="供应商" min-width="175" show-overflow-tooltip /><el-table-column label="双方确认" min-width="160"><template #default="{ row }"><span class="confirmation-pair">客 {{ confirmation(row.customerConfirmation) }} / 供 {{ confirmation(row.supplierConfirmation) }}</span></template></el-table-column><el-table-column label="进展" width="110"><template #default="{ row }"><el-tag :type="types[row.status] || 'info'" effect="plain">{{ labels[row.status] || row.status }}</el-tag></template></el-table-column><el-table-column prop="operatorName" label="负责人" width="105"><template #default="{ row }">{{ row.operatorName || '未指派' }}</template></el-table-column><el-table-column label="下次跟进" width="180"><template #default="{ row }">{{ formatDate(row.nextActionAt) }}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{ row }"><el-button v-if="!['WON','LOST'].includes(row.status)" :icon="Edit" link type="primary" @click="openFollow(row)">跟进</el-button><el-button v-else :icon="Tickets" link type="primary" @click="openFollow(row)">记录</el-button></template></el-table-column></el-table><div class="lead-pagination"><el-pagination v-model:current-page="page" :page-size="20" :total="data.total" layout="total, prev, pager, next" @current-change="load" /></div></section></template><section v-else class="lead-denied"><el-icon><Tickets /></el-icon><h2>无运营线索权限</h2><p>请使用具备平台运营权限的账号登录，再维护对接进展与结果。</p><RouterLink class="el-button el-button--primary" to="/login">前往登录</RouterLink></section>
    <el-dialog v-model="dialogVisible" :title="selected ? `${selected.demandTitle} · 运营跟进` : '运营跟进'" width="min(690px, 94vw)" class="lead-follow-dialog"><template v-if="selected"><div class="follow-meta"><span>{{ selected.customerOrganization }} → {{ selected.supplierName }}</span><el-tag :type="types[selected.status] || 'info'" effect="plain">{{ labels[selected.status] || selected.status }}</el-tag></div><p class="follow-confirmation">客户：{{ confirmation(selected.customerConfirmation) }}；供应商：{{ confirmation(selected.supplierConfirmation) }}</p><el-alert v-if="selected.status === 'MATCHED' && !(selected.customerConfirmation === 'ACCEPTED' && selected.supplierConfirmation === 'ACCEPTED')" title="双方尚未确认，暂不能标记为已联系；可关闭无效线索。" type="warning" :closable="false" show-icon /><el-form v-if="transitions.length" label-position="top" class="follow-form"><el-form-item label="更新进展"><el-segmented v-model="form.status" :options="transitions" /></el-form-item><el-form-item label="跟进说明"><el-input v-model="form.remark" type="textarea" :rows="4" maxlength="500" show-word-limit /></el-form-item><el-form-item label="下次跟进时间"><el-date-picker v-model="form.nextActionAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="选择时间" style="width:100%" /></el-form-item></el-form><section class="lead-events"><h2>过程记录</h2><el-timeline v-loading="eventLoading" v-if="events.length"><el-timeline-item v-for="event in events" :key="event.id" :timestamp="formatDate(event.createdAt)" :type="types[event.afterStatus] || 'primary'"><strong>{{ event.actorName }} · {{ event.action }}</strong><span v-if="event.remark">：{{ event.remark }}</span></el-timeline-item></el-timeline><el-empty v-else-if="!eventLoading" :image-size="48" description="尚无过程记录" /></section></template><template #footer><el-button @click="dialogVisible=false">关闭</el-button><el-button v-if="transitions.length" type="primary" :loading="saving" @click="saveFollow">保存跟进</el-button></template></el-dialog>
  </section>
</template>
